package android.widget;
public class GridLayout extends android.view.ViewGroup { public GridLayout(android.content.Context c) { super(c); } public GridLayout(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public GridLayout(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public GridLayout(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); }  private int columns=1; private int[] widths,heights; public void setColumnCount(int n) { columns=Math.max(1,n); requestLayout(); } public int getColumnCount() { return columns; } public void setRowCount(int n) {} protected void onMeasure(int ws,int hs) { int n=getChildCount(),rows=(n+columns-1)/columns; widths=new int[columns]; heights=new int[rows]; for(int i=0;i<n;i++) { android.view.View c=getChildAt(i); if(c.getVisibility()==GONE) continue; measureChild(c,ws,hs); widths[i%columns]=Math.max(widths[i%columns],c.getMeasuredWidth()); heights[i/columns]=Math.max(heights[i/columns],c.getMeasuredHeight()); } int w=getPaddingLeft()+getPaddingRight(),h=getPaddingTop()+getPaddingBottom(); for(int v:widths) w+=v; for(int v:heights) h+=v; setMeasuredDimension(resolveSize(w,ws),resolveSize(h,hs)); } protected void onLayout(boolean changed,int l,int t,int r,int b) { for(int i=0;i<getChildCount();i++) { android.view.View c=getChildAt(i); if(c.getVisibility()==GONE) continue; int x=getPaddingLeft(),y=getPaddingTop(); for(int j=0;j<i%columns;j++) x+=widths[j]; for(int j=0;j<i/columns;j++) y+=heights[j]; c.layout(x,y,x+c.getMeasuredWidth(),y+c.getMeasuredHeight()); } } }
